import * as fs from 'fs';
import * as path from 'path';

const imagesDir = path.join(__dirname, '../assets/images');

// Valid 48x48 PNG favicon (red square) - generated by ImageMagick
const favicon48Base64 = '';

// Valid 512x512 PNG icon (red square) - generated by ImageMagick
const icon512Base64 = '';

fs.writeFileSync(path.join(imagesDir, 'favicon.png'), Buffer.from(favicon48Base64, 'base64'));
fs.writeFileSync(path.join(imagesDir, 'icon.png'), Buffer.from(icon512Base64, 'base64'));

console.log('✓ Created placeholder images');
